head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gNewWidthSize = 0;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// grid resize 시작부
frame.SetEvent("onwinstat", OnWinStat);
scwin.gOldWidthSize = frame.width;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.gform_onload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21000.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS21000.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_SDate_onclick
 * @description img_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.img_SDate_onclick" });
    }
};

/**
 * @method
 * @name img_EDate_onclick
 * @description img_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.img_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀 로그
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDBNS21000.xml", SCREN_PROCS_TP_CD_07);
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        const xls_path = $c.session.getExcelDownPath() + "변동금리채금리변경일_" + today + ".xlsx";
        $c.data.downloadGridViewOffice(grd_List, "sheet1", xls_path, 8, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        scwin.showIsur(img_com_srch);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        if (row > 0) {
            scwin.fn_GetPar = scwin.getParIsuDelInfo;
            $c.bns.fn_PopIsuDetail(grd_List);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS21000.grd_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 직전영업일 가져옴
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_FRN_MGR_LIST";
    url += "&queryId=lds.stf.bnsfrn_mgr.select.list";
    url += "&SCREN_ID=" + "ULDBNS21000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_VAL=" + txb_com_abbrv.getValue();
    url += "&{P}V_STRT_DD=" + edt_SDate.getValue();
    url += "&{P}V_END_DD=" + edt_EDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sleep
 * @description sleep 처리
 * @param {*} numberMillis numberMillis
 * @returns {void}
 * @hidden N
 */
scwin.sleep = function(numberMillis) {
    let now = new Date();
    const exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};

/**
 * @method
 * @name OnSized
 * @description On Sized 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};

/**
 * @method
 * @name OnSizedMax
 * @description On Sized Max 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};

/**
 * @method
 * @name OnWinStat
 * @description On Win Stat 처리
 * @param {String} winID winID
 * @param {*} statmsg statmsg
 * @returns {void}
 * @hidden N
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg === "activate" && winID.substring(0, 6) === "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg === "maximize") {
        scwin.maxval = 1;
    } else if (statmsg === "size") {
        if (scwin.maxval === 0) {
            const strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval === 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};

/**
 * @method
 * @name GauceObjResize
 * @description 그리드메인
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    const gw = (a - parseInt(grd_List.getStyle("width")) - 30);
    grd_List.ReDraw = "false";
    grd_List.setGridWidth(parseInt(grd_List.getStyle("width")) + gw);
    grd_List.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    const pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "panel_Top");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    panel_Top.style.width = parseInt(panel_Top.style.width.replace("px", "")) + gw;
};

// grid resize 종료부

/**
 * @method
 * @name refreshForm
 * @description refresh Form 처리
 * @param {*} interval interval
 * @returns {void}
 * @hidden N
 */
scwin.refreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_com_abbrv.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_com_abbrv.setValue(arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {*} img_com_srch img_com_srch
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(img_com_srch) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(img_com_srch);
};

/**
 * @method
 * @name getParIsuDelInfo
 * @description 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        BND_LIST_PROCS_TP_CD: '2'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    await scwin.getDate();
    edt_SDate.setValue(dts_getDate.getCellData(3, "CALND_DD"));
    // edt_EDate.text = cGetToday("yyyymmdd");        // 현재날짜
    edt_EDate.setValue($c.ut.cGetPlusDate2($c.ut.cGetToday("yyyymmdd"), 3));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 5));
    await scwin.listSync();
    scwin.refreshForm(60000);
};
